# Algoritmo de Búsqueda Binaria Recursiva
def busqueda_binaria(arr, inicio, fin, valor):
    if inicio > fin: return -1
    medio = (inicio + fin) // 2
    if arr[medio] == valor: return medio
    elif valor < arr[medio]: return busqueda_binaria(arr, inicio, medio - 1, valor)
    else: return busqueda_binaria(arr, medio + 1, fin, valor)

datos = [2, 5, 8, 12, 16, 23, 38, 45, 56]
idx = busqueda_binaria(datos, 0, len(datos) - 1, 16)
print(f"Valor 16 encontrado en el indice: {idx}")

