    int n = 3;
    int* p = new int[n]; // Reserva dinamica Heap
    p[0] = 5; p[1] = 10; p[2] = 15;

    int suma = 0;
    for(int i = 0; i < n; i++) {
        suma += p[i];
    }

    cout << "Suma Heap: " << suma << endl;
    delete[] p; // Liberacion obligatoria
    return 0;
}

